// Reads the repository's docs/ at build time, through one configurable path:
// OPENFRAME_DOCS (default ../docs from the website folder). This is the only
// place the website touches anything outside openframe-website/.
//
// The MCP tool reference and the agent playbook are generated by the app
// from its tool definitions (and npm test fails when they drift), so the
// site renders those files rather than copying them: the reference here is
// always the app's. Counts quoted on the site (tools, effects, decisions...)
// are read from the same files, so they change when the docs do.
import { readFileSync, readdirSync, existsSync, statSync } from "node:fs";
import { resolve, join, relative } from "node:path";
import { unified } from "unified";
import remarkParse from "remark-parse";
import remarkGfm from "remark-gfm";
import remarkRehype from "remark-rehype";
import rehypeSlug from "rehype-slug";
import rehypeStringify from "rehype-stringify";
import { visit } from "unist-util-visit";
import type { Root as MdRoot, RootContent } from "mdast";
import type { Root as HastRoot, Element } from "hast";
import { href, repoFile } from "./site";

export const DOCS_DIR = resolve(process.env.OPENFRAME_DOCS ?? resolve(process.cwd(), "../docs"));

if (!existsSync(join(DOCS_DIR, "MCP tools.md"))) {
  throw new Error(`OpenFrame docs not found at ${DOCS_DIR}. Set OPENFRAME_DOCS to the repository's docs folder.`);
}

/** The documentation pages the site renders, in sidebar order. `source` is
 * a file in docs/; pages without one are written in the site. */
export const DOC_PAGES = [
  { slug: "", title: "Getting started", source: null, icon: "play" },
  { slug: "user-guide", title: "User guide", source: "User guide.md", icon: "scroll-text" },
  { slug: "keyboard-shortcuts", title: "Keyboard shortcuts", source: "Keyboard shortcuts.md", icon: "keyboard" },
  { slug: "mcp-tools", title: "MCP tool reference", source: "MCP tools.md", icon: "bot" },
  { slug: "agent-playbook", title: "Agent playbook", source: "Agent playbook.md", icon: "list" },
  { slug: "architecture", title: "Architecture", source: "Architecture.md", icon: "layers" },
  { slug: "contributing", title: "Contributing", source: null, icon: "heart" },
] as const;

export const docHref = (slug: string) => href("docs/" + (slug ? slug + "/" : ""));

export function readDoc(file: string): string {
  return readFileSync(join(DOCS_DIR, file), "utf8");
}

// Every markdown file under docs/, by name, for [[wiki links]].
let index: Map<string, string> | null = null;
function docIndex(): Map<string, string> {
  if (index) return index;
  index = new Map();
  const walk = (dir: string) => {
    for (const name of readdirSync(dir)) {
      if (name.startsWith(".")) continue;
      const p = join(dir, name);
      if (statSync(p).isDirectory()) walk(p);
      else if (name.endsWith(".md")) index!.set(name.slice(0, -3).toLowerCase(), relative(DOCS_DIR, p).replace(/\\/g, "/"));
    }
  };
  walk(DOCS_DIR);
  return index;
}

/** Where a [[wiki link]] goes: a page of this site when it renders that
 * doc, else the file on GitHub. */
function wikiTarget(name: string): string {
  const page = DOC_PAGES.find((p) => p.source && p.source.toLowerCase() === name.toLowerCase() + ".md");
  if (page) return docHref(page.slug);
  const rel = docIndex().get(name.toLowerCase());
  return repoFile("docs/" + (rel ?? "Index.md"));
}

/** [[Name]] (Obsidian links, sometimes wrapped over two lines) become
 * markdown links before parsing. */
function resolveWikiLinks(md: string): string {
  return md.replace(/\[\[([^\]]+?)\]\]/gs, (_, raw: string) => {
    const name = raw.replace(/\s+/g, " ").trim();
    const [target, label] = name.split("|");
    return `[${(label ?? target).trim()}](${wikiTarget(target.trim())})`;
  });
}

const GITHUB_DOCS = repoFile("docs/") + "/";

/** Relative links point at the files on GitHub; external links say so;
 * tables scroll inside a wrapper instead of widening the page. */
function rehypeSiteLinks() {
  return (tree: HastRoot) => {
    visit(tree, "element", (node: Element, i, parent) => {
      if (node.tagName === "a" && typeof node.properties.href === "string") {
        const h = node.properties.href;
        if (!/^(https?:|mailto:|#|\/)/.test(h)) node.properties.href = new URL(h, GITHUB_DOCS).href;
        if (/^https?:/.test(String(node.properties.href)) && !String(node.properties.href).startsWith("https://galexander77.github.io")) {
          node.properties.rel = ["noopener"];
        }
      }
      if (node.tagName === "table" && parent && typeof i === "number" && !(parent.type === "element" && String((parent as Element).properties?.className ?? "").includes("table-wrap"))) {
        parent.children[i] = { type: "element", tagName: "div", properties: { className: ["table-wrap"] }, children: [node] };
      }
    });
  };
}

export type Heading = { depth: number; id: string; text: string };

function headingsOf(tree: HastRoot): Heading[] {
  const out: Heading[] = [];
  visit(tree, "element", (node: Element) => {
    if (/^h[23]$/.test(node.tagName) && node.properties.id) {
      out.push({ depth: Number(node.tagName[1]), id: String(node.properties.id), text: textOf(node) });
    }
  });
  return out;
}
function textOf(node: any): string {
  if (node.type === "text") return node.value;
  return (node.children ?? []).map(textOf).join("");
}

const processor = () =>
  unified().use(remarkParse).use(remarkGfm).use(remarkRehype).use(rehypeSlug).use(rehypeSiteLinks).use(rehypeStringify);

export type Rendered = { title: string; html: string; headings: Heading[] };

/** Markdown to HTML. The document's own H1 becomes the page title. */
export function renderMarkdown(md: string): Rendered {
  const mdast = unified().use(remarkParse).use(remarkGfm).parse(resolveWikiLinks(md)) as MdRoot;
  let title = "";
  mdast.children = mdast.children.filter((n) => {
    if (n.type === "heading" && n.depth === 1 && !title) {
      title = textOf(n);
      return false;
    }
    return true;
  });
  return { title, ...renderTree(mdast) };
}

function renderTree(mdast: MdRoot): { html: string; headings: Heading[] } {
  const p = processor();
  const hast = p.runSync(mdast) as HastRoot;
  return { html: p.stringify(hast), headings: headingsOf(hast) };
}

export function renderDoc(file: string): Rendered {
  return renderMarkdown(readDoc(file));
}

// ---- the MCP tool reference, split into categories and tools

export type Tool = { name: string; id: string; summary: string; html: string };
export type ToolGroup = { name: string; id: string; intro: string; tools: Tool[] };
export type McpReference = { introHtml: string; serverText: string; groups: ToolGroup[]; total: number };

const slugify = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

export function mcpReference(): McpReference {
  const mdast = unified().use(remarkParse).use(remarkGfm).parse(resolveWikiLinks(readDoc("MCP tools.md"))) as MdRoot;
  const intro: RootContent[] = [];
  let serverText = "";
  const groups: { name: string; intro: RootContent[]; tools: { name: string; nodes: RootContent[] }[] }[] = [];
  let section = "";
  for (const n of mdast.children) {
    if (n.type === "heading" && n.depth === 1) continue;
    if (n.type === "html") continue;
    if (n.type === "heading" && n.depth === 2) {
      section = textOf(n);
      if (section !== "What the server tells a model first" && section !== "Contents") groups.push({ name: section, intro: [], tools: [] });
      continue;
    }
    if (section === "") intro.push(n);
    else if (section === "What the server tells a model first") {
      if (n.type === "code") serverText = n.value;
    } else if (section === "Contents") continue;
    else {
      const g = groups.at(-1)!;
      if (n.type === "heading" && n.depth === 3) g.tools.push({ name: textOf(n), nodes: [] });
      else if (g.tools.length) g.tools.at(-1)!.nodes.push(n);
      else g.intro.push(n);
    }
  }
  const html = (nodes: RootContent[]) => renderTree({ type: "root", children: nodes }).html;
  const out = groups.map((g) => ({
    name: g.name,
    id: slugify(g.name),
    intro: g.intro.map(textOf).join(" ").trim(),
    tools: g.tools.map((t) => {
      const first = t.nodes.find((n) => n.type === "paragraph");
      return { name: t.name, id: t.name, summary: first ? textOf(first) : "", html: html(t.nodes) };
    }),
  }));
  return { introHtml: html(intro), serverText, groups: out, total: out.reduce((a, g) => a + g.tools.length, 0) };
}

// ---- facts quoted on the site, read from the docs

const num = (re: RegExp, text: string): number | null => {
  const m = re.exec(text);
  return m ? Number(m[1]) : null;
};

export type Facts = {
  tools: number;
  decisions: number;
  firstDay: string | null;
  effects: number | null;
  transitions: number | null;
  looks: number | null;
  blendModes: number | null;
  wordArt: number | null;
  templates: number | null;
  playbooks: string[];
};

let facts: Facts | null = null;
export function getFacts(): Facts {
  if (facts) return facts;
  const features = readDoc("Features.md");
  const history = existsSync(join(DOCS_DIR, "History.md")) ? readDoc("History.md") : "";
  const decisions = existsSync(join(DOCS_DIR, "decisions"))
    ? readdirSync(join(DOCS_DIR, "decisions")).filter((f) => /^ADR-\d+.*\.md$/.test(f)).length
    : 0;
  const playbook = readDoc("Agent playbook.md");
  facts = {
    tools: mcpReference().total,
    decisions,
    firstDay: /^## (\d{4}-\d{2}-\d{2})/m.exec(history)?.[1] ?? null,
    effects: num(/(\d+) effects \(including/, features),
    transitions: num(/(\d+) transitions, \d+ looks/, features),
    looks: num(/\d+ transitions, (\d+) looks/, features),
    blendModes: num(/(\d+) blend modes/, features),
    wordArt: num(/\*\*Word art\*\*: (\d+) looks/, features),
    templates: num(/\*\*Templates\*\*: (\d+) animated/, features),
    playbooks: [...playbook.matchAll(/^## (.+)$/gm)].map((m) => m[1]).filter((h) => !/^(Design rules|Prompts)$/.test(h)),
  };
  return facts;
}

/** "2026-10-13" as "October 13, 2026". */
export const longDate = (iso: string) =>
  new Date(iso + "T12:00:00Z").toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric", timeZone: "UTC" });
